"""Rebuild only the standalone review HTML from the frozen preview JSON."""
import json
from pathlib import Path
p=Path(__file__).parent
data=json.loads((p/'PREVIEW-CONTENT.json').read_text(encoding='utf-8'))
template='''<!doctype html><html lang="zh-Hans"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Words Static · 六组学习页规划预览</title>
<style>
:root{font-family:system-ui,-apple-system,"Segoe UI",sans-serif;color:#21332d;background:#f4f5f0;font-size:17px;line-height:1.7}*{box-sizing:border-box}body{margin:0}header,main,footer{max-width:1100px;margin:auto;padding:24px}header{padding-bottom:8px}.brand{font-weight:750;letter-spacing:.02em;color:#255c4a}.notice{font-size:13px;color:#5b665f}nav{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0}button,select{font:inherit;border:1px solid #b8c9bd;background:white;color:#234e3d;border-radius:9px;padding:9px 14px;min-height:44px;cursor:pointer}button[aria-pressed=true],.primary{background:#245c49;color:white;border-color:#245c49}button:focus-visible,select:focus-visible{outline:3px solid #d0902c;outline-offset:3px}button:disabled{color:#6a736b;background:#ecefe9;cursor:default}.hero,.panel{background:#fff;border:1px solid #dbe3da;border-radius:16px;padding:26px;margin-bottom:20px}.hero{border-top:5px solid #376b54}.eyebrow{font-size:13px;color:#67766c}h1{font-size:clamp(26px,4vw,38px);line-height:1.35;margin:12px 0;overflow-wrap:anywhere}h2{font-size:23px;margin:0 0 16px}h3{font-size:18px;margin:0 0 8px}p{margin:10px 0}.meaning{font-size:22px;font-weight:650}.context{border-left:3px solid #a8bfa8;padding-left:16px}.columns{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,1fr);gap:20px;align-items:start}.dictionary-entry{padding:18px 0;border-bottom:1px solid #e1e8dd}.dictionary-entry:first-of-type{padding-top:0}.dictionary-entry:last-child{border-bottom:0}ol{padding-left:24px}li{padding-left:4px;margin:16px 0}.source{font-size:12px;color:#627366;overflow-wrap:anywhere}.en{color:#405d4d}.source-example{font-size:14px;color:#617063}.gap{padding:12px 15px;background:#f5f1e5;border-radius:8px;font-size:14px}.analysis-group{padding:0 0 16px;margin-bottom:14px;border-bottom:1px solid #e1e8dd}.actions{display:flex;gap:10px;flex-wrap:wrap}.copy{background:#f6f8f4;border-radius:10px;padding:16px}.grading{position:fixed;bottom:0;left:0;right:0;z-index:2;border-top:1px solid #dbe3da;padding:8px 16px;background:#fffffff5;display:flex;flex-wrap:wrap;gap:8px;align-items:center;justify-content:center}body:has(.grading){padding-bottom:140px}textarea{width:100%;min-height:100px;font:inherit}.front{min-height:230px;display:grid;align-content:center;text-align:center}.front button{justify-self:center}footer{font-size:13px}a{color:#245c49} [hidden]{display:none!important}@media(max-width:760px){header,main,footer{padding:16px}.hero,.panel{padding:18px}.columns{grid-template-columns:1fr;gap:0}nav button{padding:8px 12px;font-size:15px}.meaning{font-size:20px}}
</style>
<header><div class="brand">WORDS STATIC <span class="notice">／学习页设计审阅</span></div><p class="notice">独立规划预览 · 不连接学习数据库 · 不修改正式网站 · 评分仅示意</p><nav id="cases" aria-label="六组样例"></nav><label for="mode">页面状态　</label><select id="mode"><option value="lookup">直接查词</option><option value="front">背诵正面</option><option value="revealed">一次揭晓后</option></select></header><main id="content"></main>
<footer>英文词典依据：<a href="https://en-word.net/">Open English Wordnet 2025</a> · <a href="https://github.com/decidedtang-source/words-static/blob/cfa2ecc19fddf2fac7508c642f8580b1b5a85838/public/licenses/LICENSE.md">CC BY 4.0 与修改说明</a> · <a href="https://github.com/decidedtang-source/words-static/blob/cfa2ecc19fddf2fac7508c642f8580b1b5a85838/public/licenses/WNDB_License.txt">Princeton 通知</a><p>中文教学摘要、词形与简析为本项目编辑内容。所有学习例句均为自编；没有真实客户资料。源词典例句单独标注。音标未核，不补写。预览不含发音、实际评分与收藏功能；这些仍须正式实现后验收。</p></footer>
<script id="preview-data" type="application/json">__DATA__</script><script>
const DATA=JSON.parse(document.querySelector('#preview-data').textContent);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let current=DATA.cases.find(c=>c.id===location.hash.slice(1))||DATA.cases[0];const mode=document.querySelector('#mode');
function dictionary(c){return c.dictionaryEntries.map(e=>`<article class="dictionary-entry"><h3>${esc(e.lemma)} <span class="notice">${esc(({n:'名词 n.',v:'动词 v.',a:'形容词 adj.'})[e.pos]||e.pos)}</span></h3><ol>${e.senses.map(s=>`<li data-sense="${esc(s.id)}"><strong>${esc(s.glossZh)}</strong><p class="en" lang="en">${esc(s.definitionEn)}</p>${s.sourceExamples.map(x=>`<p class="source-example">源词典例句：<span lang="en">${esc(x)}</span></p>`).join('')}<p class="source">OEWN 2025 · ${esc(s.id)}</p></li>`).join('')}</ol></article>`).join('')}
function render(){document.querySelector('#cases').innerHTML=DATA.cases.map(c=>`<button data-case="${c.id}" aria-pressed="${c.id===current.id}">${c.id} · ${esc(c.id==='F'?'排程条件句':c.target)}</button>`).join('');for(const b of document.querySelectorAll('[data-case]'))b.onclick=()=>{current=DATA.cases.find(c=>c.id===b.dataset.case);location.hash=current.id;render()};const c=current,front=mode.value==='front';document.querySelector('#content').innerHTML=`<section class="hero"><div class="eyebrow">${front?'先回忆，再揭晓':mode.value==='lookup'?'查词 · 完整显示本次已选义项':'回忆之后 · 词典与简析一次显示'} ／ 样例 ${c.id}</div><h1 lang="en">${esc(c.target)}</h1><p class="notice">音标待核 · ${c.cardId?'既有卡片 '+esc(c.cardId):'预览样例，不创建学习卡'}</p><div class="context"><span class="notice">自编学习例句</span><p lang="en">${esc(c.context)}</p></div>${front?'':`<p class="meaning">${esc(c.meaning)}</p>`}</section>${front?'<section class="panel front"><p>回忆当前用法，再查看词义。</p><button class="primary" id="reveal">显示全部词义与简析</button></section>':`<div class="columns"><section class="panel" id="dictionary"><h2>词典义项</h2><p class="gap">${esc(c.gap)}</p><p class="notice">${esc(c.morphology)}</p>${dictionary(c)}</section><section class="panel" id="analysis"><h2>我们的简要解析</h2><p class="notice">从记忆、结构与辨析，到语境中的语言行动。</p>${c.groups.map(g=>`<article class="analysis-group" data-group="${g.id}"><h3>${esc(g.title)}</h3><p>${esc(g.text)}</p></article>`).join('')}<div class="copy"><h3>需要更长分析时</h3><p class="notice">复制后自行粘贴到既有 ChatGPT 项目。本页不发送内容。</p><div class="actions"><button data-copy="copyOriginal">复制原文</button><button data-copy="copyDeep">复制【深析】</button></div><p role="status" id="feedback"></p></div>${mode.value==='revealed'?'<div class="grading"><p class="notice">评分位置示意：此预览不写学习记录</p><div class="actions"><button disabled>不认识</button><button disabled>模糊</button><button disabled>认识</button></div></div>':''}</section></div>`}`;document.querySelector('#reveal')?.addEventListener('click',()=>{mode.value='revealed';render()});for(const b of document.querySelectorAll('[data-copy]'))b.onclick=async()=>{const value=c[b.dataset.copy];try{await navigator.clipboard.writeText(value);document.querySelector('#feedback').textContent='已复制；未评分、未发送。'}catch{const area=document.createElement('textarea');area.readOnly=true;area.value=value;area.setAttribute('aria-label','手工复制文本');document.querySelector('.copy textarea')?.remove();document.querySelector('.copy').append(area);area.select();document.querySelector('#feedback').textContent='请手动复制下方文本。'}}}
mode.onchange=render;addEventListener('hashchange',()=>{const next=DATA.cases.find(c=>c.id===location.hash.slice(1));if(next&&next.id!==current.id){current=next;render()}});render();
</script></html>'''
(p/'preview.html').write_text(template.replace('__DATA__',json.dumps(data,ensure_ascii=False).replace('<','\\u003c')),encoding='utf-8',newline='\n')
print('Rebuilt preview.html (isolated, no production build changes).')
